/// The status of an order.
create static entity OrderStatus public (
  Id Integer identifier required,
  Label Text(50) required,
  Order Integer required
)
values
  Open (Id = 1, Label = "Open", Order = 1),
  Closed (Id = 2, Label = "Closed", Order = 2);
/// An order of a customer.
create entity PurchaseOrder public (
  Id Long Integer identifier auto required,
  OrderNumber Text(20) required,
  OrderStatusId OrderStatus Identifier required references OrderStatus on delete Protect,
  Total Decimal(18,2) default 0,
  CreatedOn Date Time required
);
create unique index UQ_PurchaseOrder_OrderNumber on PurchaseOrder (OrderNumber);
type OrderSummary public = {
  OrderNumber: Text(20);
  Total: Decimal(18,2);
}
site property OrderLimit: Integer = 50

